import pandas as pd
import numpy as np

def extract_annual(df):
    # col0 has year with '.' and maybe numeric, col1 value.
    years=[]
    vals=[]
    for idx, val in df.iloc[:,0].items():
        if isinstance(val, (int,float)):
            # sometimes year as number maybe 1973.0
            y = int(val)
            years.append(y)
            vals.append(df.iloc[idx,1])
        elif isinstance(val,str):
            v=val.strip()
            if v.endswith('.') and v[:-1].isdigit():
                y=int(v[:-1])
                years.append(y)
                vals.append(df.iloc[idx,1])
    return pd.Series(vals, index=years)

