import pandas as pd
import numpy as np

def extract_annual(df):
    years=[]
    vals=[]
    for idx, val in df.iloc[:,0].items():
        if isinstance(val, (int,float)) and pd.notna(val):
            # probably year
            y=int(val)
            years.append(y)
            vals.append(df.iloc[idx,1])
        elif isinstance(val,str):
            v=val.strip()
            if v.endswith('.') and v[:-1].isdigit():
                y=int(v[:-1])
                years.append(y)
                vals.append(df.iloc[idx,1])
    return pd.Series(vals, index=years)

for f,sheet in [('ERP-2025-table10.xls','B10'),('ERP-2025-table12.xls','B12')]:
    df = pd.read_excel('/root/'+f, sheet_name=sheet, header=None)
    s=extract_annual(df)
    print(f, s.index.min(), s.index.max(), s.shape)
    print(s.tail())
